mapper.select:
select
c1.C_Name as bdPreparedByName,
c2.C_Name as bdAuditUnitName,
c1.C_Abbreviation as bdPreparedByAbbName,
c2.C_Abbreviation as bdAuditUnitAbbName,
pro1.P_Name as bdSplitFormName,

mn.*
from Inv_Budget_Declare mn
left join SYS_Company c1 on mn.Bd_Prepared_By=c1.C_Id
left join SYS_Company c2 on mn.Bd_Audit_Unit=c2.C_Id
left join Pre_Project pro1 on pro1.P_Id=mn.Bd_Split_Form

${params.authSql}

    and mn.Te_Id = #{params.teId}


    and mn.P_Id=#{params.pId}


    and mn.Bd_Prepared_By = #{params.bdPreparedBy}


    and mn.Bd_Audit_Unit = #{params.bdAuditUnit}


    and mn.Bd_Split_Type = #{params.bdSplitType}


    and mn.Bd_Type = #{params.bdType}


    
        
            and likeCname(#{params.bdPreparedByName},c1.C_Id)=true
        
        
            and likeCname(#{params.bdAuditUnitName},c2.C_Id)=true
        
        
            and likePname(#{params.pName},pro.P_Id)=true
        
    
    
        
            and c1.C_Name like concat('%',#{params.bdPreparedByName},'%')
        
        
            and c2.C_Name like concat('%',#{params.bdAuditUnitName},'%')
        
        
            and pro.P_Name like concat('%',#{params.pName},'%')
        
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Bd_Create_Time DESC

select * from Inv_Budget_Declare

    
        P_Id=#{pId}
    
    
        and Bd_State=#{bdState}
    
    
        and Bd_Type in
        
            #{bdType}
